WITH payload AS (SELECT '{{$json.payload_sql}}'::jsonb AS body)
INSERT INTO content_events (job_id,event_type,message,metadata)
SELECT NULLIF(body->>'job_id','')::uuid, COALESCE(NULLIF(body->>'event_type',''),'progress'), COALESCE(NULLIF(body->>'message',''),'Progress update'), COALESCE(body->'metadata','{}'::jsonb) FROM payload;
SELECT NULLIF('{{$json.job_id}}','') AS job_id, 'logged' AS status;

WITH payload AS (SELECT '{{$json.payload_sql}}'::jsonb AS body)
INSERT INTO content_errors (job_id, severity, error_code, error_message, recoverable, context)
SELECT NULLIF(body->>'job_id','')::uuid, COALESCE(NULLIF(body->>'severity',''),'warning'), COALESCE(NULLIF(body->>'error_code',''),'STEP_FAILED'), COALESCE(body->>'error_message',''), true, jsonb_build_object('step_name',COALESCE(NULLIF(body->>'step_name',''),'unknown'),'retry_safe','retry_count < max_retries','retry_count',COALESCE(NULLIF(body->>'retry_count',''),'0')) FROM payload;
SELECT NULLIF('{{$json.job_id}}','') AS job_id, 'logged' AS status;

