const base = $node['Normalize And Auth'].json;
const retrySafe = Number(base.retry_count || 0) < Number(base.max_retries || 3);
const results = [...(base.tool_results || []), {tool: 'tool_logging', status: 'logged', retry_safe: retrySafe}];
return [{json: {...base, ...$json, retry_safe: retrySafe, note: 'retry_count < max_retries', tool_results: results}}];
